UPDATE public.nutrition_tips SET title_de = COALESCE(title_de, 'Folatreiche Lebensmittel'), content_de = COALESCE(content_de, 'Im ersten Trimester der Schwangerschaft ist Folat besonders wichtig. Dunkelgrünes Blattgemüse, Zitrusfrüchte und Hülsenfrüchte sind gute Quellen.') WHERE id = '3cd9d02f-2306-400b-bf13-48f59e00d6e0';
